     3→namespace App\Http\Controllers\Broadcasting;
     4→
     5→use Illuminate\Http\Request;
     6→use Illuminate\Http\JsonResponse;
     7→use App\Http\Controllers\Controller;
     8→use Illuminate\Support\Facades\Auth;
     9→
    10→class BroadcastingController extends Controller
    11→{
    12→    /**
    13→     * Autenticar usuario para canales privados de WebSocket.
    14→     *
    15→     * @param Request $request
    16→     * @return JsonResponse
    17→     * @author Andres Gonzalez
    18→     */
    19→    public function autenticar(Request $request): JsonResponse {
    20→        // Obtener configuración de Reverb
    21→        $clave_app = config('broadcasting.connections.reverb.key');
    22→        $secreto_app = config('broadcasting.connections.reverb.secret');
    23→        
    24→        // Obtener datos de la petición
    25→        $socket_id = $request->input('socket_id');
    26→        $nombre_canal = $request->input('channel_name');
    27→        
    28→        // Validar que todos los datos necesarios estén presentes
    29→        if (!$socket_id || !$nombre_canal || !$clave_app || !$secreto_app) {
    30→            return response()->json(['error' => 'Datos faltantes'], 400);
    31→        }
    32→        
    33→        // Verificar autorización del canal privado
    34→        if (preg_match('/private-App\.Models\.Usuarios\.User\.(\d+)/', $nombre_canal, $coincidencias)) {
    35→            $usuario_solicitado_id = (int) $coincidencias[1];
    36→            $usuario_actual_id = Auth::id();
    37→            
    38→            // Solo permitir acceso al propio canal del usuario
    39→            if ($usuario_actual_id !== $usuario_solicitado_id) {
    40→                return response()->json(['error' => 'No autorizado'], 403);
    41→            }
    42→        }
    43→        
    44→        // Generar signature para autenticación
    45→        $cadena_para_firmar = $socket_id . ':' . $nombre_canal;
    46→        $firma = hash_hmac('sha256', $cadena_para_firmar, $secreto_app);
    47→        $cadena_autenticacion = $clave_app . ':' . $firma;
    48→        
    49→        // Retornar cadena de autenticación
    50→        return response()->json([
    51→            'auth' => $cadena_autenticacion
    52→        ]);
    53→    }
    54→}
